const mapping: Record<string,string> = {"codex": "codex", "claude": "claudecode-color", "kimi": "kimi-color", "kimicode": "kimi-color", "pi": "pi", "piagent": "pi", "gemini": "geminicli-color", "opencode": "opencode", "qoder": "qoder-color", "qodercli": "qoder-color", "hermes": "hermesagent", "deepseek": "deepseek-color", "agy": "antigravity-color", "copilot": "githubcopilot"};
